fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    // Specification:
    // Requires:
    //   - always true (no preconditions)
    // Ensures:
    //   - returns false if input is empty
    //   - otherwise returns true iff
    //       1) last character is an ASCII letter
    //       2) AND either input length is 1, or the character before last is a space

    // Get an iterator over the characters of the string
    let mut chars = txt.chars();

    // Early return false if empty
    if chars.next().is_none() {
        // Input string empty
        // So result must be false
        return false;
    }

    // Collect all characters into a vector for indexing
    let chars_vec: Vec<char> = txt.chars().collect();
    let len = chars_vec.len();

    // Last character
    let last_char = chars_vec[len - 1];

    // Check if last char is ASCII alphabetic
    if !last_char.is_ascii_alphabetic() {
        return false;
    }

    // Check if last char is standalone:
    // Either the string length is exactly 1
    // OR the character before last is a space
    if len == 1 {
        true
    } else {
        chars_vec[len - 2] == ' '
    }
}